package com.gerenciadorrural.modules.organizations.api;
import com.gerenciadorrural.modules.organizations.application.ResolveTenantContext; import com.gerenciadorrural.shared.tenancy.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/context") public class TenantContextController {
 @GetMapping public ResponseEntity<Response> get(@ResolvedTenantContext TenantContext context,HttpServletRequest request){var resolved=(ResolveTenantContext.Resolved)request.getAttribute(ResolvedTenantContextArgumentResolver.RESOLVED_ATTRIBUTE);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Response.from(resolved));}
 public record Response(String userId,Organization organization,Farm farm,Membership membership){static Response from(ResolveTenantContext.Resolved r){var c=r.context();return new Response(c.userId().toString(),new Organization(c.tenantId().toString(),r.organizationName()),new Farm(c.farmId().toString(),r.farmName()),new Membership(c.membershipId().toString(),c.role(),c.farmScopeMode()));}} public record Organization(String id,String name){} public record Farm(String id,String name){} public record Membership(String id,String role,String farmScopeMode){}
}
